function compressImage(dataUrl,maxW,quality,cb){maxW=maxW||600;quality=quality||0.5;var img=new Image();img.onload=function(){var w=img.width,hh=img.height;if(w>maxW){hh=Math.round(hh*maxW/w);w=maxW;}if(hh>maxW){w=Math.round(w*maxW/hh);hh=maxW;}var c=document.createElement('canvas');c.width=w;c.height=hh;c.getContext('2d').drawImage(img,0,0,w,hh);var result=c.toDataURL('image/jpeg',quality);if(result.length>200000&&quality>0.2){compressImage(dataUrl,Math.round(maxW*0.7),quality-0.15,cb);}else{cb(result);}};img.onerror=function(){cb(dataUrl);};img.src=dataUrl;}
function showImagePicker(opts){var title=opts.title||'Select Image',current=opts.currentUrl||'',onConfirm=opts.onConfirm||function(){},maxW=opts.maxWidth||600,quality=opts.quality||0.5;var ov=document.createElement('div');ov.className='inner-modal-overlay';ov.innerHTML='<div class="inner-modal" style="max-width:340px"><div class="modal-header"><span class="modal-title">'+esc(title)+'</span><button class="modal-close" id="ip-close"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M18 6L6 18M6 6l12 12"/></svg></button></div><div class="image-picker"><div class="image-picker-preview" id="ip-preview">'+(current?'<img src="'+esc(current)+'" />':'Tap to select')+'</div><div class="image-picker-actions"><button id="ip-local">Local</button><button id="ip-url-mode">URL</button><button id="ip-clear">Clear</button></div><div id="ip-url-row" style="display:none;margin-top:0.3rem"><input id="ip-url" class="s-input" value="" placeholder="https://..." /></div><div id="ip-status" style="font-size:0.6rem;color:var(--text-3);margin-top:0.1rem"></div></div><button class="s-btn" id="ip-confirm" style="margin-top:0.3rem;width:100%">Confirm</button></div>';document.body.appendChild(ov);var resultUrl=current;var isUrlMode=false;document.getElementById('ip-close').addEventListener('click',function(){ov.remove();});ov.addEventListener('click',function(e){if(e.target===ov)ov.remove();});document.getElementById('ip-url-mode').addEventListener('click',function(){isUrlMode=!isUrlMode;document.getElementById('ip-url-row').style.display=isUrlMode?'':'none';this.style.background=isUrlMode?'var(--primary)':'';this.style.color=isUrlMode?'#fff':'';});document.getElementById('ip-local').addEventListener('click',function(){var inp=document.createElement('input');inp.type='file';inp.accept='image/*';inp.addEventListener('change',function(){var f=inp.files[0];if(!f)return;var st=document.getElementById('ip-status');if(st)st.textContent='Compressing...';var r=new FileReader();r.onload=function(){compressImage(r.result,maxW,quality,function(compressed){resultUrl=compressed;var pv=document.getElementById('ip-preview');if(pv)pv.innerHTML='<img src="'+compressed+'" />';var kb=Math.round(compressed.length*0.75/1024);if(st)st.textContent=kb+'KB';});};r.readAsDataURL(f);});inp.click();});var urlInput=document.getElementById('ip-url');if(urlInput)urlInput.addEventListener('input',debounce(function(){var u=this.value.trim();if(!u)return;resultUrl=u;var pv=document.getElementById('ip-preview');if(pv)pv.innerHTML='<img src="'+esc(u)+'" onerror="this.parentElement.innerHTML=\'Failed\'" />';},600));document.getElementById('ip-clear').addEventListener('click',function(){resultUrl='';var pv=document.getElementById('ip-preview');if(pv)pv.innerHTML='Tap to select';var ui=document.getElementById('ip-url');if(ui)ui.value='';});document.getElementById('ip-confirm').addEventListener('click',function(){var urlVal=(document.getElementById('ip-url')||{}).value||'';var finalUrl=urlVal.trim()||resultUrl;ov.remove();try{onConfirm(finalUrl);}catch(e){onConfirm(finalUrl);}});}
