function parseChatSummary(text){var regex=/<聊天纪要>\s*([\s\S]*?)\s*\|\s*([\s\S]*?)\s*\|\s*([\s\S]*?)\s*\|\s*([\s\S]*?)\s*<\/聊天纪要>/;var match=text.match(regex);if(!match)return null;var clean=text.replace(regex,'').trim();var time=match[1].trim(),place=match[2].trim(),event=match[3].trim(),color=match[4].trim();if(!color.match(/^#/))color='#888';var card='<div style="margin:6px 0;max-width:100%;font-family:system-ui,sans-serif"><div style="background:var(--surface-2);border-radius:10px;padding:8px 10px;position:relative;overflow:hidden;border:0.5px solid var(--border-light)"><div style="position:absolute;top:0;left:0;width:3px;height:100%;background:'+color+'"></div><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:5px"><span style="font-size:0.62em;color:var(--text-3);font-weight:500">Status</span><span style="font-size:0.58em;background:'+color+';color:#fff;padding:1px 6px;border-radius:8px;opacity:0.85">'+esc(time)+'</span></div><div style="display:flex;gap:6px;flex-direction:column"><div style="font-size:0.68em;color:var(--text-2)"><span style="opacity:0.5">Location:</span> '+esc(place)+'</div><div style="font-size:0.72em;color:var(--text);line-height:1.35;background:var(--surface-3);padding:5px 7px;border-radius:6px">'+esc(event)+'</div></div></div></div>';return{clean:clean,card:card};}
function parseAICards(fullText,senderInfo){var cards=[];var cleanText=fullText;var patterns=[{regex:/\[(转账|Transfer)[：:]([^\]]+)\]/i,type:'transfer',field:'amount'},{regex:/\[(外卖|Delivery|点餐)[：:]([^\]]+)\]/i,type:'delivery',field:'item'},{regex:/\[(礼物|Gift|送礼)[：:]([^\]]+)\]/i,type:'gift',field:'item'},{regex:/\[(图片|照片|Photo|Image)[：:]([^\]]+)\]/i,type:'ai-image',field:'desc'},{regex:/\[(语音|Voice|语音消息)[：:]([^\]]+)\]/i,type:'ai-voice',field:'desc'},{regex:/\[(相册|Album|Photo Album)[：:]([^\]]+)\]/i,type:'album-photo',field:'desc'}];patterns.forEach(function(p){var m=cleanText.match(p.regex);if(m){var card={role:'model',ts:Date.now()+cards.length*150,content:m[0],type:p.type};if(senderInfo){card.senderName=senderInfo.name;card.senderAvatar=senderInfo.avatar;}if(p.type==='transfer'){card.amount=m[2].trim();card.toName='You';}else if(p.type==='delivery'){card.item=m[2].trim();}else if(p.type==='gift'){card.item=m[2].trim();card.toName='You';}else if(p.type==='album-photo'){var matched=window.AIPhotoAlbum&&window.AIPhotoAlbum.match?window.AIPhotoAlbum.match(m[2].trim()):null;if(matched){card.type='image';card.content=matched.url;}else{card.desc=m[2].trim();card.type='ai-image';}}else{card.desc=m[2].trim();}cards.push(card);cleanText=cleanText.replace(m[0],'').trim();}});return{cleanText:cleanText,cards:cards};}
