function applyBubbleCSS(convId,msgEl){var s=Storage.getConvSettings(convId),css=s.bubbleCSS||{},presets=Storage.getBubblePresets(),preset=s.bubblePreset&&presets[s.bubblePreset]?presets[s.bubblePreset]:{};var wrap=msgEl.closest('.conv-wrap')||msgEl.parentElement;if(!wrap)return;var vars={'--cb-me-bg':css.meBg||preset.meBg||'','--cb-me-color':css.meColor||preset.meColor||'','--cb-me-radius':css.meRadius||preset.meRadius||'','--cb-me-shadow':css.meShadow||preset.meShadow||'','--cb-me-border':css.meBorder||preset.meBorder||'','--cb-ai-bg':css.aiBg||preset.aiBg||'','--cb-ai-color':css.aiColor||preset.aiColor||'','--cb-ai-radius':css.aiRadius||preset.aiRadius||'','--cb-ai-shadow':css.aiShadow||preset.aiShadow||'','--cb-ai-border':css.aiBorder||preset.aiBorder||'','--cb-font-size':css.fontSize||'','--cb-spacing':css.spacing||''};Object.keys(vars).forEach(function(k){if(vars[k])wrap.style.setProperty(k,vars[k]);else wrap.style.removeProperty(k);});var bg=s.chatBackground||'';if(bg){if(bg.indexOf('http')===0||bg.indexOf('data:')===0){msgEl.style.setProperty('background-image','url("'+bg+'")','important');msgEl.style.setProperty('background-size','cover','important');msgEl.style.setProperty('background-position','center','important');}else{msgEl.style.setProperty('background',bg,'important');msgEl.style.backgroundImage='';}}else{msgEl.style.background='';msgEl.style.backgroundImage='';}var customCode=css.customCode||'';var styleId='custom-css-'+convId.replace(/[^a-zA-Z0-9_-]/g,'_');var old=document.getElementById(styleId);if(old)old.remove();if(customCode.trim()){var el=document.createElement('style');el.id=styleId;el.textContent=customCode;document.head.appendChild(el);}}
function showTimeStatus(convId,friend,msgEl){var ts=Storage.getTimeSettings();if(!ts.enabled)return;var cs=Storage.getCharacterTimeStatus();var name=(friend.displayName||friend.name||'');var text=cs.status==='sleeping'?name+' is sleeping...':cs.status==='busy'?name+' is busy':name+' is available';msgEl.appendChild(h('div','time-status-bar','<span>'+text+'</span>'));}
function checkProactiveMessages(convId,friend,msgEl){var ts=Storage.getTimeSettings();if(!ts.enabled||!ts.proactiveEnabled)return;var awayMins=Storage.getAwayMinutes();if(awayMins<ts.proactiveInterval)return;var apiKey=Storage.get('apiKey','');if(!apiKey)return;var cs=Storage.getCharacterTimeStatus();if(cs.status==='sleeping')return;var name=(friend.realName||friend.displayName||friend.name||'').trim()||'AI';var awayText=awayMins>=60?Math.floor(awayMins/60)+'h'+(awayMins%60>0?(awayMins%60)+'m':''):awayMins+'m';var built=window.buildApiUrl('/chat/completions');fetch(built.url,{method:'POST',headers:built.headers,body:JSON.stringify({model:Storage.get('modelName','gpt-3.5-turbo'),messages:[{role:'system',content:'You are '+name+'. '+(friend.prompt||'')},{role:'user',content:'User away '+awayText+'. Send 1-2 short msgs. Separate with |||. Output only.'}],temperature:0.9,stream:false})}).then(function(r){if(!r.ok)throw new Error('');return r.json();}).then(function(data){var text='';try{text=data.choices[0].message.content;}catch(e){}if(!text)return;text.split('|||').map(function(s){return s.trim();}).filter(Boolean).forEach(function(part,i){setTimeout(function(){Storage.appendMessage(convId,{role:'model',content:part,ts:Date.now()-(2-i)*60000,senderName:name,isProactive:true});maybeInsertDateSep(msgEl,Date.now());msgEl.appendChild(h('div','chat-ts',fmtTime(Date.now())));msgEl.appendChild(h('div','proactive-msg',esc(part)));scrollToBottom(msgEl);},i*300);});}).catch(function(){});}

function renderChatList(){var friends=Storage.getFriends(),groups=Storage.getGroups(),pinned=Storage.getPinned();var c=getContent();if(!c)return;var items=[];friends.forEach(function(f){var msgs=Storage.getMessages(f.id);var last=msgs.length?msgs[msgs.length-1]:null;items.push({id:f.id,type:'friend',name:(f.displayName||f.name||'').trim(),avatar:f.avatar||'',lastText:last?((last.content||'').indexOf('__PLUGIN__:')===0?'[System]':(last.content||'').replace(/<聊天纪要>[\s\S]*?<\/聊天纪要>/g,'').slice(0,24)):'No messages',lastTs:last?last.ts:0,unread:Storage.getUnread(f.id),pinned:pinned.indexOf(f.id)>=0,data:f});});groups.forEach(function(g){var msgs=Storage.getMessages(g.id);var last=msgs.length?msgs[msgs.length-1]:null;items.push({id:g.id,type:'group',name:g.name||'Group',avatar:g.avatar||'',memberIds:g.memberIds||[],lastText:last?last.content.slice(0,24):'No messages',lastTs:last?last.ts:0,unread:Storage.getUnread(g.id),pinned:pinned.indexOf(g.id)>=0,data:g});});items.sort(function(a,b){if(a.pinned&&!b.pinned)return-1;if(!a.pinned&&b.pinned)return 1;return b.lastTs-a.lastTs;});if(!items.length){c.innerHTML='<div class="tab-empty"><p>No conversations</p></div>';return;}var html='<div style="padding:0.4rem 0.55rem 0"><div class="search-bar"><span class="search-icon">&#128269;</span><input id="chat-search" placeholder="Search..." /></div></div><div class="friend-list" id="chat-list">';items.forEach(function(item){var avHtml='';if(item.type==='group'){if(item.avatar){avHtml='<img class="friend-avatar" src="'+esc(item.avatar)+'" />';}else{var allF=Storage.getFriends();avHtml='<div class="group-avatar-stack">';(item.memberIds||[]).slice(0,3).forEach(function(mid){var mf=allF.find(function(f){return f.id===mid;});avHtml+='<img src="'+esc(mf?mf.avatar:'')+'" />';});avHtml+='</div>';}}else{var unreadCls=item.unread>0?' has-unread':'';avHtml='<img class="friend-avatar'+unreadCls+'" src="'+esc(item.avatar)+'" />';}html+='<div class="friend-row" data-cid="'+item.id+'" data-ctype="'+item.type+'">'+avHtml+'<div class="friend-info"><div class="friend-name">'+esc(item.name)+(item.pinned?'<span class="pin-icon">&#128204;</span>':'')+'</div><div class="friend-last">'+esc(item.lastText)+'</div></div>'+(item.unread>0?'<span class="unread-badge">'+(item.unread>99?'99+':item.unread)+'</span>':'')+'</div>';});html+='</div>';c.innerHTML=html;var list=document.getElementById('chat-list');if(list)list.addEventListener('click',function(e){var row=e.target.closest('.friend-row');if(!row)return;if(row.dataset.ctype==='group')openGroupConversation(row.dataset.cid);else openConversation(row.dataset.cid);});var si=document.getElementById('chat-search');if(si)si.addEventListener('input',debounce(function(){var q=si.value.trim().toLowerCase();list.querySelectorAll('.friend-row').forEach(function(r){var n=(r.querySelector('.friend-name')||{}).textContent||'';r.style.display=(!q||n.toLowerCase().indexOf(q)>=0)?'':'none';});},150));}
function hideTabBar(){var b=document.querySelector('.chat-tabbar');if(b)b.style.display='none';}
