function openConversation(fid){currentFriendId=fid;currentIsGroup=false;replyingTo=null;var friends=Storage.getFriends();var friend=friends.find(function(f){return f.id===fid;});if(!friend)return;Storage.clearUnread(fid);var cs=Storage.getConvSettings(fid);if(cs.charAvatar&&cs.charAvatar!==friend.avatar){friend.avatar=cs.charAvatar;Storage.upsertFriend(friend);}if(cs.userAvatar){var au=Storage.getActiveUser();if(au&&cs.userAvatar!==au.avatar){au.avatar=cs.userAvatar;Storage.upsertUser(au);}}var ac=Storage.getActiveCharacter()||{};var aiName=(friend.realName||friend.displayName||friend.name||'').trim()||(ac.name||'').trim()||'AI';var alias=(friend.displayName||friend.name||'').trim();hideTabBar();var c=getContent();c.innerHTML=buildConvHTML(friend,aiName,alias,false);var msgEl=document.getElementById('conv-messages');applyBubbleCSS(fid,msgEl);renderAllMessages(fid,msgEl);if(msgEl){msgEl.scrollTop=msgEl.scrollHeight;}bindConvEvents(fid,friend,msgEl,false);showTimeStatus(fid,friend,msgEl);checkProactiveMessages(fid,friend,msgEl);Storage.recordVisit();if(Storage.isBlocked(fid)){var bb=h('div','block-banner','<span>Contact blocked</span><button id="conv-unblock">Unblock</button>');msgEl.parentElement.insertBefore(bb,msgEl);document.getElementById('conv-unblock').addEventListener('click',function(){Storage.setBlocked(fid,false);bb.remove();var ie=document.getElementById('conv-input');if(ie){ie.disabled=false;ie.placeholder='Message...';}document.getElementById('conv-send').disabled=false;document.getElementById('conv-ai').disabled=false;});var ie=document.getElementById('conv-input');if(ie){ie.disabled=true;ie.placeholder='Blocked';}document.getElementById('conv-send').disabled=true;document.getElementById('conv-ai').disabled=true;}}
function openGroupConversation(gid){currentFriendId=gid;currentIsGroup=true;replyingTo=null;var group=Storage.getGroups().find(function(g){return g.id===gid;});if(!group)return;Storage.clearUnread(gid);hideTabBar();var c=getContent();c.innerHTML=buildConvHTML(group,group.name,'',true);var msgEl=document.getElementById('conv-messages');applyBubbleCSS(gid,msgEl);renderAllMessages(gid,msgEl);if(msgEl){msgEl.scrollTop=msgEl.scrollHeight;}bindConvEvents(gid,group,msgEl,true);Storage.recordVisit();}
function buildConvHTML(entity,displayName,subtitle,isGroup){var avEl='';if(isGroup){if(entity.avatar){avEl='<img class="conv-avatar-sm" src="'+esc(entity.avatar)+'" />';}else{var allF=Storage.getFriends();avEl='<div class="group-avatar-stack" style="width:2rem;height:2rem">';(entity.memberIds||[]).slice(0,3).forEach(function(mid){var mf=allF.find(function(f){return f.id===mid;});avEl+='<img style="width:1.2rem;height:1.2rem" src="'+esc(mf?mf.avatar:'')+'" />';});avEl+='</div>';}}else{avEl='<img class="conv-avatar-sm" src="'+esc(entity.avatar||'')+'" />';}return '<div class="conv-wrap"><div class="conv-header"><button class="btn-icon-sm" id="conv-back"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M15 18l-6-6 6-6"/></svg></button>'+avEl+'<div style="display:flex;flex-direction:column;line-height:1.2;flex:1;min-width:0"><span class="conv-name" style="white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+esc(displayName)+'</span>'+(subtitle&&subtitle!==displayName?'<span style="font-size:0.65rem;opacity:0.4">'+esc(subtitle)+'</span>':'')+'</div><div class="conv-header-actions"><button class="btn-icon-sm" id="conv-clear"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M3 6h18M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/></svg></button><button class="btn-icon-sm" id="conv-more"><svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor"><circle cx="12" cy="5" r="1.5"/><circle cx="12" cy="12" r="1.5"/><circle cx="12" cy="19" r="1.5"/></svg></button></div></div><div class="chat-messages" id="conv-messages"></div><div id="reply-bar-slot"></div><div class="chat-input-bar" style="position:relative"><div class="action-sheet" id="action-sheet"><div class="action-grid">'+buildActionGrid()+'</div></div><button class="chat-plus-btn" id="conv-plus">+</button><textarea class="chat-textarea" id="conv-input" rows="1" placeholder="Message..."></textarea><button class="chat-action-btn chat-send-btn" id="conv-send"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M22 2L11 13"/><path d="M22 2L15 22L11 13L2 9L22 2Z"/></svg></button><button class="chat-action-btn chat-ai-btn" id="conv-ai"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 2a4 4 0 0 1 4 4v2H8V6a4 4 0 0 1 4-4z"/><rect x="3" y="8" width="18" height="12" rx="2"/><path d="M9 15h0M15 15h0"/></svg></button></div></div>';}
function bindConvEvents(convId,entity,msgEl,isGroup){document.getElementById('conv-back').addEventListener('click',function(){currentFriendId=null;currentIsGroup=false;replyingTo=null;showTabBar();renderChatList();});document.getElementById('conv-send').addEventListener('click',function(){sendUserMsg(convId,msgEl);});document.getElementById('conv-ai').addEventListener('click',function(){if(isGroup)triggerGroupAIReply(convId,entity,msgEl);else triggerAIReply(convId,entity,msgEl);});var inputEl=document.getElementById('conv-input');inputEl.addEventListener('keydown',function(e){if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendUserMsg(convId,msgEl);}});inputEl.addEventListener('input',debounce(function(){inputEl.style.height='auto';inputEl.style.height=Math.min(inputEl.scrollHeight,112)+'px';},50));document.getElementById('conv-clear').addEventListener('click',function(e){e.preventDefault();e.stopPropagation();Storage.clearMessages(convId);msgEl.innerHTML='';Toast.success('Cleared');});document.getElementById('conv-more').addEventListener('click',function(){showMorePanel(convId,entity,msgEl,isGroup);});bindActionSheet(convId,entity,msgEl,isGroup);bindContextMenu(convId,entity,msgEl,isGroup);}
function renderAllMessages(convId,msgEl){msgEl.innerHTML='';var messages=Storage.getMessages(convId);var settings=Storage.getConvSettings(convId);var lastDate='';messages.forEach(function(m,idx){if(m.role==='user'&&typeof m.content==='string'&&m.content.indexOf('__PLUGIN__:')===0)return;var dl=getDateLabel(m.ts);if(dl!==lastDate){msgEl.appendChild(h('div','date-separator','<span>'+dl+'</span>'));lastDate=dl;}appendBubble(msgEl,m,idx,settings,convId);});}
