function streamResponse(convId,entity,msgEl,messages,aiBubble,aiBtn,senderInfo){var built=window.buildApiUrl('/chat/completions');var model=Storage.get('modelName','gpt-3.5-turbo');var temperature=Storage.getTemperature();fetch(built.url,{method:'POST',headers:built.headers,body:JSON.stringify({model:model,messages:messages,temperature:temperature,stream:true})}).then(function(r){if(!r.ok)return r.text().then(function(t){var m;try{var j=JSON.parse(t);m=(j.error&&(j.error.message||j.error.code))||t.slice(0,200);}catch(_){m=t.slice(0,200);}throw new Error('HTTP '+r.status+' - '+m);});var reader=r.body.getReader(),decoder=new TextDecoder(),fullText='';aiBubble.classList.remove('thinking');aiBubble.textContent='';function read(){return reader.read().then(function(res){if(res.done){if(fullText){var parsed=parseAICards(fullText,senderInfo);var cardMsgs=parsed.cards;var textContent=parsed.cleanText;cardMsgs.forEach(function(card){Storage.appendMessage(convId,card);});if(textContent){var shouldRecall=Math.random()<0.08;var maxBubbles=8;

/* ═══ 智能断句 v5 ═══ */
/* ═══ 智能断句 v7 — 动态气泡数 ═══ */
/* ═══ 真人聊天断句 v8 ═══ */
var _splitMsg=function(text){
  if(!text)return [text];
  /* 核心修复：把 AI 误发的 "\\n" 文本转成真正的换行符 */
  var cleanText = text.replace(/\\n/g, "\n");
  var maxB=8;
  var byLine=cleanText.split(/\n+/).map(function(s){return s.trim();}).filter(Boolean);
  if(byLine.length>=2) return byLine.slice(0,maxB);
  var src=cleanText.trim();
  if(src.length<=18)return [src];
  var emoWords=["哈哈哈","哈哈","笑死","啊？","可以呀","好耶","天哪","救命","绝了","离谱","好好好","對对对","행","ㅋㅋㅋ","ㅎㅎ","진짜","대박","아이고","헐","lol","haha","omg"];
  var parts=[]; var remain=src;
  var maxLen=20; var minLen=4;
  while(remain.length>0 && parts.length < maxB){
    if(remain.length <= maxLen || parts.length === maxB-1){ parts.push(remain); remain=""; break; }
    var cutAt=-1; var wnd=Math.min(maxLen, remain.length-1);
    for(var i=wnd;i>=minLen;i--){ if("\u3002\uff01\uff1f!?~\uff5e\u2026\uff0c,\u3001 ".indexOf(remain.charAt(i))>=0){cutAt=i;break;} }
    if(cutAt<0) cutAt=wnd;
    parts.push(remain.slice(0,cutAt+1).trim());
    remain=remain.slice(cutAt+1).trim();
  }
  return parts.filter(Boolean);
};

var parts=_splitMsg(textContent);
if(parts.length>1){parts.forEach(function(part,pi){var aiMsg={role:'model',content:part.trim(),ts:Date.now()+pi*100+(cardMsgs.length*150),recalled:pi===0?shouldRecall:false};if(senderInfo){aiMsg.senderName=senderInfo.name;aiMsg.senderAvatar=senderInfo.avatar;}Storage.appendMessage(convId,aiMsg);});Storage.addToken(fullText.length);if(currentFriendId!==convId){Storage.addUnread(convId);showNotification(entity,fullText);}renderAllMessages(convId,msgEl);scrollToBottom(msgEl);if(aiBtn)aiBtn.disabled=false;return;}var aiMsg={role:'model',content:textContent,ts:Date.now()+(cardMsgs.length*150),recalled:shouldRecall};if(senderInfo){aiMsg.senderName=senderInfo.name;aiMsg.senderAvatar=senderInfo.avatar;}Storage.appendMessage(convId,aiMsg);Storage.addToken(fullText.length);if(currentFriendId!==convId){Storage.addUnread(convId);showNotification(entity,fullText);}renderAllMessages(convId,msgEl);scrollToBottom(msgEl);if(shouldRecall){setTimeout(function(){if(currentFriendId===convId){var typingEl2=h('div','typing-indicator','<span>typing</span><span class="typing-dots"><span></span><span></span><span></span></span>');msgEl.appendChild(typingEl2);scrollToBottom(msgEl);setTimeout(function(){if(typingEl2.parentNode)typingEl2.remove();msgEl.appendChild(h('div','chat-ts',fmtTime(Date.now())));var ab2=h('div','chat-bubble ai thinking','...');msgEl.appendChild(ab2);scrollToBottom(msgEl);streamResponse(convId,entity,msgEl,messages,ab2,aiBtn,senderInfo);},800);}},1500);return;}}else if(cardMsgs.length){Storage.addToken(fullText.length);if(currentFriendId!==convId){Storage.addUnread(convId);showNotification(entity,fullText);}renderAllMessages(convId,msgEl);scrollToBottom(msgEl);}}if(aiBtn)aiBtn.disabled=false;return;}var chunk=decoder.decode(res.value,{stream:true});chunk.split('\n').forEach(function(line){line=line.trim();if(!line||line==='data: [DONE]')return;if(line.indexOf('data: ')===0){try{var j=JSON.parse(line.slice(6));var d=j.choices&&j.choices[0]&&j.choices[0].delta;if(d&&d.content){fullText+=d.content;aiBubble.textContent=fullText;scrollToBottom(msgEl);}}catch(e){}}});return read();});}return read();}).catch(function(e){aiBubble.textContent='Error: '+e.message;aiBubble.style.color='var(--error)';aiBubble.classList.remove('thinking');if(aiBtn)aiBtn.disabled=false;});}
