if(window.AIPhotoAlbum&&window.AIPhotoAlbum.getAll){var aiPhotos=window.AIPhotoAlbum.getAll();if(aiPhotos.length){systemPrompt+='\n\n## AI Photo Album\nYou have real photos you can send. Use [相册:keyword] to send a matching photo.\nAvailable photos:\n'+aiPhotos.map(function(p){return '- [相册:'+p.desc+']'+(p.tags?' (tags: '+p.tags+')':'');}).join('\n')+'\nOnly use when contextually natural. The photo will appear as a real image.';}}
