function triggerGroupAIReply(convId,group,msgEl){var ie=document.getElementById('conv-input');if(ie&&ie.value.trim())sendUserMsg(convId,msgEl);var members=(group.memberIds||[]);if(!members.length)return;var friends=Storage.getFriends();var mode=group.replyMode||'sequential';var rid;if(mode==='random'){rid=members[Math.floor(Math.random()*members.length)];}else{var msgs2=Storage.getMessages(convId);var lastAi=null;for(var i=msgs2.length-1;i>=0;i--){if(msgs2[i].role==='model'&&msgs2[i].senderName){lastAi=msgs2[i];break;}}if(lastAi){var lm=members.find(function(mid){var f=friends.find(function(x){return x.id===mid;});return f&&(f.realName||f.displayName||f.name)===lastAi.senderName;});var li=lm?members.indexOf(lm):-1;rid=members[(li+1)%members.length];}else{rid=members[0];}}var resp=friends.find(function(f){return f.id===rid;});if(!resp)return;var cn=(resp.realName||resp.displayName||resp.name||'').trim();maybeInsertDateSep(msgEl,Date.now());var typingEl=h('div','typing-indicator','<span>'+esc(cn)+' typing</span><span class="typing-dots"><span></span><span></span><span></span></span>');msgEl.appendChild(typingEl);scrollToBottom(msgEl);var aiBtn=document.getElementById('conv-ai');if(aiBtn)aiBtn.disabled=true;setTimeout(function(){if(typingEl.parentNode)typingEl.remove();msgEl.appendChild(h('div','chat-ts',fmtTime(Date.now())));var settings=Storage.getConvSettings(convId);var row=h('div','msg-row');if(settings.showAvatars){var av=h('img','msg-avatar');av.src=resp.avatar||'';av.style.background='#E8E0E0';av.onerror=function(){this.src='';this.style.background='#E8E0E0';};row.appendChild(av);}var body=h('div','msg-body');body.appendChild(h('div','msg-sender-tag',esc(cn)));var ab=h('div','chat-bubble ai thinking','...');body.appendChild(ab);row.appendChild(body);msgEl.appendChild(row);scrollToBottom(msgEl);doCardAck(convId);streamResponse(convId,group,msgEl,buildPromptMessages(convId,resp,cn),ab,aiBtn,{name:cn,avatar:resp.avatar});},1000);}
