function buildStickerAssignHTML(fid){var groups=Storage.getStickerGroups();var assigned=Storage.getFriendStickerGroups(fid);if(!groups.length)return '<div style="font-size:0.65rem;color:var(--text-3)">No groups</div>';return '<div class="sticker-assign-list">'+groups.map(function(g){var checked=assigned.indexOf(g.id)>=0;return '<div class="sticker-assign-row"><span class="assign-name">'+esc(g.name)+'</span><span class="assign-count">'+((g.stickers||[]).length)+'</span><div class="dark-mode-toggle'+(checked?' active':'')+'" data-assign-gid="'+g.id+'" style="width:2rem;height:1.1rem"></div></div>';}).join('')+'</div>';}
