function aiAnalyzeMemory(convId,friend,parentOv){var apiKey=Storage.get('apiKey','');if(!apiKey)return;var messages=Storage.getMessages(convId);if(messages.length<5)return;var hist=messages.slice(-40).filter(function(m){return!(m.role==='user'&&typeof m.content==='string'&&m.content.indexOf('__PLUGIN__:')===0);}).map(function(m){return(m.role==='user'?'User':'AI')+': '+m.content;}).join('\n');var built=window.buildApiUrl('/chat/completions');fetch(built.url,{method:'POST',headers:built.headers,body:JSON.stringify({model:Storage.get('modelName','gpt-3.5-turbo'),messages:[{role:'system',content:'Return JSON: {"habits":["..."],"likes":["..."],"events":[{"text":"...","strength":"high/medium/low"}]}'},{role:'user',content:hist}],temperature:0.3,stream:false})}).then(function(r){if(!r.ok)throw new Error('');return r.json();}).then(function(data){var text='';try{text=data.choices[0].message.content;}catch(e){}var jm=text.match(/\{[\s\S]*\}/);if(!jm)return;try{var r=JSON.parse(jm[0]);if(r.habits)r.habits.forEach(function(x){Storage.addMemoryEntry(convId,'habits',{text:typeof x==='string'?x:x.text||''});});if(r.likes)r.likes.forEach(function(x){Storage.addMemoryEntry(convId,'likes',{text:typeof x==='string'?x:x.text||''});});if(r.events)r.events.forEach(function(x){Storage.addMemoryEntry(convId,'events',{text:typeof x==='string'?x:x.text||'',strength:(x&&x.strength)||'medium'});});if(parentOv)parentOv.remove();showMemoryPanel(convId,friend);}catch(e){}}).catch(function(){});}
function showAddGroupMember(group,parentOv,convId,msgEl,isGroup){var friends=Storage.getFriends();var avail=friends.filter(function(f){return(group.memberIds||[]).indexOf(f.id)<0;});if(!avail.length)return;var ov=document.createElement('div');ov.className='inner-modal-overlay';ov.innerHTML='<div class="inner-modal"><div class="modal-header"><span class="modal-title">Add Member</span><button class="modal-close" id="gm-close"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M18 6L6 18M6 6l12 12"/></svg></button></div><div class="friend-list">'+avail.map(function(f){return '<div class="friend-row" data-fid="'+f.id+'"><img class="friend-avatar" src="'+esc(f.avatar)+'" /><div class="friend-info"><div class="friend-name">'+esc(f.displayName||f.name||'')+'</div></div></div>';}).join('')+'</div></div>';document.body.appendChild(ov);document.getElementById('gm-close').addEventListener('click',function(){ov.remove();});ov.addEventListener('click',function(e){if(e.target===ov)ov.remove();});ov.querySelector('.friend-list').addEventListener('click',function(e){var row=e.target.closest('.friend-row');if(!row)return;group.memberIds=(group.memberIds||[]).concat([row.dataset.fid]);Storage.upsertGroup(group);ov.remove();parentOv.remove();showMorePanel(convId,group,msgEl,isGroup);});}
